	@Test
	public void testCollisionsSurviveMultipleIndexGrowthSteps() throws IOException {
		LmdbCountAliasIndex index = new LmdbCountAliasIndex();
		int collisionHash = 0x7f4a7c15;
		Set<Long> collisionIds = new HashSet<>();
		Map<Integer, Long> uniqueIds = new HashMap<>();
		try {
			index.open();
			for (int i = 0; i < 24; i++) {
				int hash = i < 4 ? collisionHash : 0x100000 + i * 7919;
				long id = 1000L + i;
				index.add(hash, id);
				if (i < 4) {
					collisionIds.add(id);
				} else {
					uniqueIds.put(hash, id);
				}
			}

			assertThat(idsFor(index, collisionHash)).containsExactlyInAnyOrderElementsOf(collisionIds);
			for (Map.Entry<Integer, Long> entry : uniqueIds.entrySet()) {
				assertThat(idsFor(index, entry.getKey())).containsExactly(entry.getValue());
			}
		} finally {
			index.close();
		}
		assertThat(index.isValid()).isFalse();
	}

