	private static List<Long> idsFor(LmdbCountAliasIndex index, int hash) {
		List<Long> ids = new ArrayList<>();
		long ordinal = index.first(hash);
		while (ordinal != 0) {
			index.position(ordinal);
			if (index.hash() == hash) {
				ids.add(index.id());
			}
			ordinal = index.next();
		}
		return ids;
	}

